   "这个岗位每天干什么": "三级安全教育、隐患排查整改、动火和高空作业审批、做安全资料、迎接安全检查、处理安全事故、应急预案演练。",
   "审核时怎么问": "项目上出过安全事故或未遂没有？三级教育怎么做的、给谁做？动火证谁批、需要什么条件？最近迎接什么检查、查出什么隐患、怎么整改的？",
   "能查到哪些证据": "安全员C证（住建系统可查）；安全资料签字；隐患排查记录；安全教育台账；社保。",
   "真干过的人怎么答": "熟悉安全规范术语，能讲具体隐患整改案例，知道应急上报流程和时间要求，能说出检查频次。",
   "没干过的破绽": "说不清C证；把安全员说成\"看大门的\"；不懂三级教育是哪三级；不知道事故上报流程。",
