   "真干过的人怎么答": "能报出在手项目数量与装机容量（kW），讲得清彩钢瓦要用夹具或导轨不破坏防水、水泥屋顶用配重块不打孔，知道备案要提供屋顶产权或租赁协议、电网接入要走供电所申请与验收，会提到组件朝向倾角影响发电量、遮挡会造成热斑。",
