   "审批要点": "户用光伏行业“光伏贷”套路高发，务必核实项目备案与并网手续是否齐全、EPC资质有效性、屋顶产权或租赁协议真实性；项目经理是否实际在岗直接影响项目合规性，手续不全的项目无法并网发电、还款来源落空。"
