   "审核时怎么问": "你一天能装多少块板、多少千瓦？组件压块怎么固定、扭矩多少？接地线你怎么做、为什么要接地？屋顶作业你系安全带吗、谁监督？",
   "能查到哪些证据": "社保或劳务协议；高处作业证或登高证（应急管理部门可查）；本人签字的施工记录与安装量统计；现场施工照片；工资或计件结算单；安全交底记录。",
   "真干过的人怎么答": "能报出日均安装量（通常一天数十块组件、几千瓦到十几千瓦），讲得清压块固定与扭矩要求、组件不能踩踏与磕碰（隐裂影响发电），知道接地是为了防雷与漏电保护、要用镀锌扁钢或铜线，会提到屋顶作业必须系安全带、高温天要防中暑。",
