   "能查到哪些证据": "社保；本人签订的农户合同与屋顶租赁协议；现场勘查照片与测量记录；应收账款或贷款办理记录；客户档案与跟进记录；提成结算单；宣传物料。",
   "真干过的人怎么答": "能报出月签户数与单户装机容量，讲得清合作模式差异（企业租屋顶农户收租金、农户自投、农户贷款买设备企业代建），知道贷款模式下农户要背还款义务、必须明确告知，会提到农户最关心的是收益兑现与漏水问题，说得出当地光照资源与发电收益测算方式。",
