   "审批要点": "这是“光伏贷”风险最高的岗位，必须核实合同是否清晰告知农户贷款性质与还款义务、有无夸大发电收益、有无诱导签字；若业务员以“租屋顶免费装”话术实际让农户背贷，属欺诈性营销，相关贷款违约率极高，是明确的重大风险信号。"
